	return operation;
}

export function createWorkoutsReplaceExercisesOperation(
	adapter: WorkoutsReplaceExercisesAdapter,
): WorkoutsReplaceExercisesOperation {
	const effect = Effect.fn("operations.workouts.replaceExercises")(function* (
