			Effect.map((response) => ({
				workout: isEmptyResponse(response) ? null : (response ?? null),
			})),
			Effect.catchIf(
				(error) => isExpectedReadNotFound(error, "/v1/workouts"),
				() =>
					Effect.succeed({
						workout: null,
						expected404Outcome: "not_found" as const,
					}),
			),
		);
	});

